const days=[
['10/7 수','D-18','진단 시험: 2023-1회를 시험 모드(150분)로 풀고, 틀린 문항마다 오답 사유를 고릅니다.',1,0],['10/8 목','D-17','C: 포인터, 구조체, 배열, 재귀. 섹션별 기출을 추적표로 풉니다.',1,0],['10/9 금','D-16','Java: 클래스, 상속, 오버라이딩, static, 예외. 오후에는 Python 문법 함정을 정리합니다.',1,1],['10/10 토','D-15','SQL/DB: DDL·DML·DCL, JOIN, GROUP BY, 정규화, 관계대수. 테스트 기법·디자인 패턴·UML.',1,1],['10/11 일','D-14','이론: 보안, 네트워크, OS, 요구사항, 인터페이스, 패키징. 키워드 카드 완성 후 오답 재풀이.',1,1],
['10/12 월','D-13','2023-2회 (90분 타이머) → 채점, 오답 정리',2,0],['10/13 화','D-12','2023-3회',2,0],['10/14 수','D-11','2024-1회',2,0],['10/15 목','D-10','2024-2회',2,0],['10/16 금','D-9','2024-3회',2,0],['10/17 토','D-8','09:30부터 2025-1회 시험 모드. 오후에는 오답을 섹션별로 묶어 두 번째 풀이.',2,1],['10/18 일','D-7','2021~2022년 이론 단답 회독. 코드 문제는 C·Java만 골라 풉니다.',2,1],['10/19 월','D-6','약점 집중 1: 먼저 볼 섹션의 기출 풀이',2,0],['10/20 화','D-5','약점 집중 2, 오답 2회독 마무리, 함정 리스트 초안',2,0],
['10/21 수','D-4','2025-2회 시험 모드 → 오답 정리',3,0],['10/22 목','D-3','2025-3회 시험 모드 → 아직 못 맞히는 오답 최종 재풀이',3,0],['10/23 금','D-2','2026-1회 복원문제 시험 모드. 없으면 오답 회독으로 대체합니다.',3,0],['10/24 토','D-1','09:30 2026-2회 복원문제. 오후에는 함정 리스트와 키워드 카드만 봅니다. 준비물 확인.',3,1],['10/25 일','D-Day','아침에 함정 리스트 1장만 보고, 09:30 1부 시험에 들어갑니다.',3,0]];
const exams=['2023-1회','2023-2회','2023-3회','2024-1회','2024-2회','2024-3회','2025-1회','2025-2회','2025-3회','2026-1회','2026-2회'];
const seedCards=[['결합도 순서','약 → 강: 자료 · 스탬프 · 제어 · 외부 · 공통 · 내용 (자스제외공내)'],['응집도 순서','강 → 약: 기능 · 순차 · 교환 · 절차 · 시간 · 논리 · 우연 (기순교절시논우)'],['SQL 절 순서','SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY'],['sizeof vs strlen','sizeof("abc") = 4 / strlen("abc") = 3']];
const key='dday-study-v1';let state=JSON.parse(localStorage.getItem(key)||'null')||{done:[],scores:[],reviews:[],cards:seedCards};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];function save(){localStorage.setItem(key,JSON.stringify(state));renderStats()}function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
$$('nav button').forEach(b=>b.onclick=()=>{$$('.view').forEach(v=>v.classList.remove('active'));$$('nav button').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');b.classList.add('active')});
function currentIndex(){const n=new Date(),m=n.getMonth()+1,d=n.getDate();if(m!==10)return n<new Date(n.getFullYear(),9,7)?0:18;return Math.max(0,Math.min(18,d-7))}
function renderToday(){const i=currentIndex(),x=days[i];$('#todayDate').textContent=x[0]+(x[4]?' · 휴일':'');$('#dayCount').textContent=x[1];$('#todayD').textContent=`DAY ${String(i+1).padStart(2,'0')} · ${x[1]}`;$('#todayTitle').textContent=i===18?'시험 당일':'오늘의 집중 과제';$('#todayTask').textContent=x[2];$('#todayPhase').textContent=x[3]+'단계';$('#todayCheck').checked=state.done.includes(i);$('#todayCheck').onchange=e=>{e.target.checked?state.done.push(i):state.done=state.done.filter(n=>n!==i);save();renderTimeline();toast(e.target.checked?'오늘도 해냈어요.':'완료를 취소했어요.')};}
function renderStats(){const pct=Math.round(state.done.length/days.length*100);$('#progressText').textContent=pct+'%';$('#progressBar').style.width=pct+'%';$('#latestScore').textContent=state.scores.length?state.scores.at(-1).score+'점':'—';$('#dueCount').textContent=state.reviews.filter(r=>r.stage<2).length}
let phase='all';function renderTimeline(){const box=$('#timeline');box.innerHTML='';days.forEach((x,i)=>{if(phase!=='all'&&String(x[3])!==phase)return;const row=document.createElement('article');row.className='day-row '+(state.done.includes(i)?'done':'');row.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><time class="${x[4]?'holiday':''}">${x[0]}${x[4]?' ★':''}<small>${x[1]} · ${x[3]}단계</small></time><div class="task">${x[2]}</div><input aria-label="완료" type="checkbox" ${state.done.includes(i)?'checked':''}>`;row.querySelector('input').onchange=e=>{state.done=e.target.checked?[...new Set([...state.done,i])]:state.done.filter(n=>n!==i);save();renderTimeline();renderToday()};box.append(row)})}
$$('.phase-filters button').forEach(b=>b.onclick=()=>{$$('.phase-filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');phase=b.dataset.phase;renderTimeline()});
function renderScores(){$('#examSelect').innerHTML=exams.map(x=>`<option>${x}</option>`).join('');$('#scoreList').innerHTML=state.scores.slice(-4).reverse().map(s=>`<div class="score-item"><span>${s.exam}</span><b>${s.score}점</b></div>`).join('')||'<p class="muted">아직 기록된 점수가 없습니다.</p>'}
$('#scoreForm').onsubmit=e=>{e.preventDefault();const score=+$('#scoreInput').value;if(score<0||score>100)return;state.scores.push({exam:$('#examSelect').value,score});$('#scoreInput').value='';save();renderScores();toast('점수를 기록했어요.')};
function renderReviews(){$('#reviewList').innerHTML=state.reviews.map((r,i)=>`<article class="review-item"><header><b>${r.id}</b><span class="tag">${r.reason}</span></header><p>${r.note}</p><footer><button class="mini" data-stage="${i}">${r.stage===0?'1회 복습 완료':r.stage===1?'2회 연속 정답':'복습 완료 ✓'}</button><button class="mini danger" data-del-review="${i}">삭제</button></footer></article>`).join('')||'<p class="muted">오답을 추가하면 복습 주기를 추적할 수 있어요.</p>';$$('[data-stage]').forEach(b=>b.onclick=()=>{state.reviews[b.dataset.stage].stage=Math.min(2,state.reviews[b.dataset.stage].stage+1);save();renderReviews()});$$('[data-del-review]').forEach(b=>b.onclick=()=>{state.reviews.splice(b.dataset.delReview,1);save();renderReviews()})}
$('#reviewForm').onsubmit=e=>{e.preventDefault();state.reviews.unshift({id:$('#questionId').value,reason:$('#reason').value,note:$('#answerNote').value,stage:0});e.target.reset();save();renderReviews();toast('오답을 복습 목록에 넣었어요.')};
function renderCards(){$('#cardGrid').innerHTML=state.cards.map((c,i)=>`<article class="study-card" data-card="${i}"><div class="card-inner"><div class="card-face"><small>QUESTION ${String(i+1).padStart(2,'0')}</small><h2>${c[0]}</h2><small>눌러서 정답 보기 ↗</small></div><div class="card-face card-back"><small>ANSWER</small><p>${c[1]}</p><button class="mini danger" data-del-card="${i}">삭제</button></div></div></article>`).join('');$$('.study-card').forEach(c=>c.onclick=e=>{if(!e.target.matches('button'))c.classList.toggle('flipped')});$$('[data-del-card]').forEach(b=>b.onclick=()=>{state.cards.splice(b.dataset.delCard,1);save();renderCards()})}
$('#cardForm').onsubmit=e=>{e.preventDefault();state.cards.push([$('#cardFront').value,$('#cardBack').value]);e.target.reset();save();renderCards();toast('새 카드를 만들었어요.')};
$('#reset').onclick=()=>{if(confirm('모든 진도와 기록을 초기화할까요?')){state={done:[],scores:[],reviews:[],cards:seedCards};save();renderAll();toast('초기화했습니다.')}};
function renderAll(){renderToday();renderStats();renderTimeline();renderScores();renderReviews();renderCards()}renderAll();
